def _EncodeText(value, codepage):
    codepage = int(codepage)
    if codepage == 65001:
        return value.encode("utf-8")
    table = _SINGLE_BYTE_TABLES.get(codepage)
    if table is not None:
        output = []
        for character in value:
            index = table.find(character)
            output.append(chr(index) if index >= 0 else "?")
        return "".join(output)
    try:
        return value.encode("cp%s" % codepage, "replace")
    except LookupError:
        return value.encode("utf-8")


def ApplyLocale(language, codepage):
    for moduleName, entries in TRANSLATIONS.items():
        module = localeInfo if moduleName == "localeInfo" else uiScriptLocale
        for key, variants in entries.items():
            value = variants.get(language, variants.get("en"))
            if value is not None:
                setattr(module, key, _EncodeText(value, codepage))

