def ApplyLayout(window, category):
    styles = GetLayouts().get(category, {})
    for path, fields in EVALUATED_LAYOUT.get(category, {}).items():
        styles.setdefault(path, {}).update(fields)
    def visit(node, path):
        path += "/" + node.get("name", "")
        node.update(styles.get(path, {}))
        if node.get("type") in ("text", "adjust_text"):
            node.setdefault("fontname", "Tahoma:12")
        for child in node.get("children", ()):
            visit(child, path)
    visit(window, "")

